sparql_response:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?composer ?deathPlace ?deathPlaceLabel WHERE {
  <http://dbpedia.org/resource/Love_Is_Here_to_Stay> dbo:composer ?composer .
  ?composer dbo:deathPlace ?deathPlace .
  OPTIONAL { ?deathPlace rdfs:label ?deathPlaceLabel . FILTER (lang(?deathPlaceLabel) = "en") }
}
LIMIT 100

